-- MANAGEMENT-PERSONAS-3 / ECOSYSTEM-LOOP-1 (2026-10-26, pillar autonomy). Owner directive 2026-10-26 06:49Z, verbatim (project chat):
--   "IDENTIFY AND REMEDIATE ROOT CAUSES OF REPEATED ERRORS/ISSUES/FAILURES SYSTEMWIDE ACROSS THE FLEET AND DEPLOY ALL CHANGES.
--    INTEGRATE FLEET PORTFOLIO/PROGRAM/PROJECT ROADMAPS/PLANS/STRATEGY/ISSUES/BACKLOGS/ETC INTO SELF-UPDATING, SELF-IMPROVING
--    ECOSYSTEM (WHATEVER THAT MEANS). THE FLEET SHALL CONTINUE IMPROVING ITS OWN QUALITY AND SHALL KEEP GETTING "BETTER" AUTOMATICALLY"
--
-- The layers already update themselves on their own hourly ticks: roadmap-backlog-sync (:00) puts every open critical/high issue,
-- failure mode and goal on roadmap_implementation and verifies it when it closes; roadmap-self-maintain (:30) completes and reopens
-- goals on their DoD probes; the portfolio-* workflows (:10 to :50) keep projects and programs on the roadmap. What was missing is the
-- loop that learns from outcomes: nothing read which failures keep coming back, and nothing measured whether the fleet is getting better.
-- Measured 2026-10-26 06:55Z: issue_lifecycle holds 627 reopens in 7 days against 905 opens; CF-OBS-ISSUE-1 issues were reopened 149
-- times (44 issues), PORTFOLIO-GAP 134 times (2 issues), LOOP-BREAKER-1 30, METRIC-REGISTRY-STALENESS-1 28, FLEET-JOURNEY-FAILED-1 24;
-- 207 metric triggers hold a value and 68 of them are in breach.
--
-- WHAT THE MANAGERS' HOURLY TICK NOW DOES (fleet_tasks management-personas, every decision a persona_actions row)
--   1. recurrence: issue_recurrence_now snapshots, per issue family (title prefix; METRIC-TRIGGER-<id> per trigger), the reopens and
--      new issues of the last 7 days and 24 hours.
--   2. root cause: a family reopened 5 or more times in 7 days and still active in the last 24 hours gets one critical
--      "ROOT-CAUSE-1: <family> keeps recurring" issue (top 10 families), mapped to the program of its latest issue. Critical puts it
--      in its program's focus at the front of the code loop's queue, and roadmap-backlog-sync puts it on the roadmap. It closes with
--      evidence once the family has had no reopen and no new issue for 24 hours (and reopens through issue_refile_reopen if it recurs).
--   3. quality trend: quality_trend records each hour, for the fleet and each program, the share of measured metric triggers on target
--      (0..100) and the reopens of the last 7 days; metrics fleet_quality_index and issue_reopens_7d carry the fleet values.
--   4. output quality: the portfolio brief also states the verdict of v_output_quality_headline (OUTPUT-QUALITY-LEDGER-1, PR 4309:
--      outcome measures per surface), so operational and output quality are read in one place.
--   5. strategy from outcomes: a program whose quality index fell 5 points or more in 24 hours is escalated by the portfolio manager
--      (focus raised by half), exactly as a risk rise is; the briefs state the index, its 24-hour change and the most recurring families.
--
-- Stop the decisions without a deploy: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('persona_actions', 'off');
-- (measurement continues; fleet_crons management-personas-hourly enabled = 0 stops everything).
-- Verify after apply:
--   SELECT status, error FROM fleet_runs WHERE task_id = 'management-personas' ORDER BY id DESC LIMIT 3;
--   SELECT * FROM quality_trend ORDER BY tick DESC LIMIT 6;
--   SELECT id, title FROM agent_issues WHERE title LIKE 'ROOT-CAUSE-1:%' AND status = 'open';
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261026_issues_mp3
-- Rollback: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('persona_actions', 'off'); restore the MANAGEMENT-PERSONAS-2 workflow and plan view by re-running the fleet_tasks and CREATE VIEW statements of migrations/2026-10-26-management-personas-2.sql (DROP VIEW IF EXISTS v_portfolio_allocation_plan first); ROOT-CAUSE-1 issues stay as filed (close them with evidence).

CREATE TABLE IF NOT EXISTS bak_20261026_issues_mp3 AS SELECT id, title, priority, status FROM agent_issues WHERE status = 'open';

CREATE TABLE IF NOT EXISTS issue_recurrence_now (
  family TEXT PRIMARY KEY,
  reopens_7d INTEGER NOT NULL,
  issues_7d INTEGER NOT NULL,
  reopens_24h INTEGER NOT NULL,
  opens_24h INTEGER NOT NULL,
  last_issue_id INTEGER,
  program_code TEXT,
  project_code TEXT,
  computed_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS quality_trend (
  tick TEXT NOT NULL,
  scope TEXT NOT NULL,
  measured INTEGER,
  in_breach INTEGER,
  reopens_7d INTEGER,
  quality_index REAL,
  computed_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  PRIMARY KEY (tick, scope)
);

CREATE VIEW IF NOT EXISTS v_root_cause_quiet AS
SELECT a.id AS issue_id, COALESCE(m.program_code, 'QNFO.OPS') AS program_code,
  'MANAGEMENT-PERSONAS-3 recurrence stopped: family ' || substr(a.title, 15, instr(a.title, ' keeps recurring') - 15)
    || ' had no reopen and no new issue in the last 24 hours (issue_lifecycle, read ' || strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    || '); a new recurrence re-files and reopens this issue' AS evidence
FROM agent_issues a
LEFT JOIN issue_project_map m ON m.issue_id = a.id
WHERE a.status = 'open' AND a.title LIKE 'ROOT-CAUSE-1: % keeps recurring'
  AND a.created_at < (CAST(strftime('%s', 'now') AS INTEGER) - 86400) * 1000
  AND NOT EXISTS (SELECT 1 FROM issue_recurrence_now r WHERE r.family = substr(a.title, 15, instr(a.title, ' keeps recurring') - 15)
    AND r.reopens_24h + r.opens_24h > 0)
  AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN ('active', 'holding')
    AND COALESCE(c.last_verdict, '') IN ('fail', 'vacuous-probe-result', 'probe-error', 'probe-not-machine-executable', 'probe-same-account-host'))
  AND COALESCE((SELECT value FROM ops_config WHERE key = 'persona_actions'), 'on') <> 'off';

DROP VIEW IF EXISTS v_portfolio_allocation_plan;
CREATE VIEW v_portfolio_allocation_plan AS
WITH cfg AS (
  SELECT COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = 'persona_focus_slots' AND CAST(value AS INTEGER) > 0), 25) AS slots
),
r AS (
  SELECT p.program_code, p.manager_persona, p.verdict, p.risk, p.open_issues,
    (SELECT a.risk_score FROM portfolio_allocations a WHERE a.program_code = p.program_code
       AND a.tick <= strftime('%Y-%m-%dT%H:00Z', 'now', '-24 hours') ORDER BY a.tick DESC LIMIT 1) AS risk_24h,
    (SELECT q.quality_index FROM quality_trend q WHERE q.scope = p.program_code AND q.tick = strftime('%Y-%m-%dT%H:00Z', 'now')) AS q_now,
    (SELECT q.quality_index FROM quality_trend q WHERE q.scope = p.program_code AND q.tick <= strftime('%Y-%m-%dT%H:00Z', 'now', '-24 hours') ORDER BY q.tick DESC LIMIT 1) AS q_24h
  FROM program_risk_now p
),
tot AS (
  SELECT COALESCE(SUM(risk), 0) AS t, MAX(risk) AS mx, COUNT(*) AS n FROM program_risk_now WHERE open_issues > 0
),
d AS (
  SELECT r.program_code, r.manager_persona, r.verdict, r.risk, r.risk_24h, r.q_now, r.q_24h, r.open_issues, tot.t AS total_risk,
    CASE WHEN r.open_issues = 0 THEN 'idle'
         WHEN r.risk = tot.mx AND r.risk > 0 THEN 'constrain'
         WHEN r.risk_24h IS NOT NULL AND r.risk > r.risk_24h * 1.1 THEN 'escalate'
         WHEN r.q_24h IS NOT NULL AND r.q_now IS NOT NULL AND r.q_now <= r.q_24h - 5 THEN 'escalate'
         WHEN r.risk_24h IS NOT NULL AND r.risk < r.risk_24h * 0.8 THEN 'accelerate'
         WHEN r.verdict = 'GREEN' THEN 'maintain'
         ELSE 'steady' END AS decision,
    CASE WHEN r.open_issues = 0 THEN 0
         ELSE MAX(1, (cfg.slots / 2) / MAX(1, tot.n) + CAST(ROUND((cfg.slots - cfg.slots / 2) * r.risk / MAX(tot.t, 0.0001)) AS INTEGER)) END AS base_slots
  FROM r, tot, cfg
)
SELECT program_code, manager_persona, verdict, risk, risk_24h, open_issues, decision,
  MIN(open_issues, CASE decision WHEN 'escalate' THEN base_slots + (base_slots + 1) / 2 WHEN 'maintain' THEN 1 WHEN 'idle' THEN 0 ELSE base_slots END) AS slots,
  CASE decision
    WHEN 'constrain' THEN 'highest risk in the portfolio (' || risk || ' of ' || ROUND(total_risk, 1) || '): it is the constraint and gets the largest share of focus'
    WHEN 'escalate' THEN CASE WHEN risk_24h IS NOT NULL AND risk > risk_24h * 1.1 THEN 'risk rose from ' || risk_24h || ' to ' || risk || ' in 24h' ELSE 'quality fell from ' || q_24h || ' to ' || q_now || ' of 100 in 24h' END || ': focus raised by half'
    WHEN 'accelerate' THEN 'risk fell from ' || risk_24h || ' to ' || risk || ' in 24h: keep the current focus moving'
    WHEN 'maintain' THEN 'GREEN: one focus slot keeps the program watched'
    WHEN 'idle' THEN 'no open issue mapped to the program'
    ELSE verdict || ', risk ' || risk || ': focus in proportion to risk' END AS reason
FROM d;

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('management-personas', 'MANAGEMENT-PERSONAS-1/2/3: portfolio manager allocates focus, demotes stale fleet criticals and escalates on falling quality; program managers pick focus, promote and restore, close recovered and quiet issues, supersede duplicates and file root-cause issues for recurring families; quality trend and briefs', 'workflow',
  '{"steps":[{"type":"sql","name":"recur-clear","db":"AUDIT","sql":"DELETE FROM issue_recurrence_now"},{"type":"sql","name":"recur-snapshot","db":"AUDIT","sql":"INSERT OR REPLACE INTO issue_recurrence_now (family, reopens_7d, issues_7d, reopens_24h, opens_24h, last_issue_id, program_code, project_code) SELECT x.family, x.reopens_7d, x.issues_7d, x.reopens_24h, x.opens_24h, x.last_issue_id, m.program_code, m.project_code FROM (SELECT CASE WHEN a.title LIKE ''METRIC-TRIGGER-%'' THEN substr(a.title, 1, 14 + instr(substr(a.title, 16), ''-'')) ELSE substr(a.title, 1, MIN(CASE WHEN instr(a.title, '' '') > 0 THEN instr(a.title, '' '') ELSE 999 END, CASE WHEN instr(a.title, '':'') > 0 THEN instr(a.title, '':'') ELSE 999 END) - 1) END AS family, SUM(CASE WHEN l.event = ''reopened'' THEN 1 ELSE 0 END) AS reopens_7d, COUNT(DISTINCT l.issue_id) AS issues_7d, SUM(CASE WHEN l.event = ''reopened'' AND l.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') THEN 1 ELSE 0 END) AS reopens_24h, SUM(CASE WHEN l.event = ''opened'' AND l.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') THEN 1 ELSE 0 END) AS opens_24h, MAX(l.issue_id) AS last_issue_id FROM issue_lifecycle l JOIN agent_issues a ON a.id = l.issue_id WHERE l.event IN (''opened'', ''reopened'') AND l.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'') AND a.title NOT LIKE ''ROOT-CAUSE-1:%'' GROUP BY 1) x LEFT JOIN issue_project_map m ON m.issue_id = x.last_issue_id WHERE x.family <> '''' AND x.reopens_7d > 0"},{"type":"sql","name":"rc-file","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''ROOT-CAUSE-1: '' || r.family || '' keeps recurring'', ''MANAGEMENT-PERSONAS-3 (ECOSYSTEM-LOOP-1): issues of the family '' || r.family || '' were reopened '' || r.reopens_7d || '' times across '' || r.issues_7d || '' issues in 7 days (latest #'' || r.last_issue_id || ''). A fix that holds changes the producer or the probe that keeps closing and reopening them, not the individual issues. The program manager of '' || COALESCE(r.program_code, ''QNFO.OPS'') || '' keeps this issue in focus; it closes on its own once the family has had no reopen and no new issue for 24 hours, and reopens if the family recurs.'', ''management-personas'', ''reliability'', ''critical'', ''open'', CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000, CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 FROM issue_recurrence_now r WHERE r.reopens_7d >= 5 AND r.reopens_24h + r.opens_24h > 0 AND r.family IN (SELECT family FROM issue_recurrence_now WHERE reopens_7d >= 5 ORDER BY reopens_7d DESC LIMIT 10) AND NOT EXISTS (SELECT 1 FROM agent_issues b WHERE b.title = ''ROOT-CAUSE-1: '' || r.family || '' keeps recurring'' AND b.status = ''open'') AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off''"},{"type":"sql","name":"rc-map","db":"AUDIT","sql":"INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at) SELECT a.id, COALESCE(r.project_code, ''W.OPS''), COALESCE(r.program_code, ''QNFO.OPS''), ''fix'', datetime(''now'') FROM agent_issues a JOIN issue_recurrence_now r ON a.title = ''ROOT-CAUSE-1: '' || r.family || '' keeps recurring'' WHERE a.status = ''open''"},{"type":"sql","name":"rc-file-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || COALESCE(r.program_code, ''QNFO.OPS''), ''root-cause'', a.id, NULL, ''open'', r.family || '' reopened '' || r.reopens_7d || '' times in 7 days across '' || r.issues_7d || '' issues'' FROM agent_issues a JOIN issue_recurrence_now r ON a.title = ''ROOT-CAUSE-1: '' || r.family || '' keeps recurring'' WHERE a.status = ''open'' AND NOT EXISTS (SELECT 1 FROM persona_actions p WHERE p.issue_id = a.id AND p.kind = ''root-cause'' AND p.reverted_at IS NULL)"},{"type":"sql","name":"rc-close-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT issue_id, ''recurrence-stopped'', ''triaged'', ''management-personas'', datetime(''now''), evidence FROM v_root_cause_quiet WHERE 1 ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"rc-close-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || program_code, ''close'', issue_id, ''open'', ''closed'', evidence FROM v_root_cause_quiet"},{"type":"sql","name":"rc-close-mark","db":"AUDIT","sql":"UPDATE persona_actions SET reverted_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE kind = ''root-cause'' AND reverted_at IS NULL AND issue_id IN (SELECT issue_id FROM v_root_cause_quiet)"},{"type":"sql","name":"rc-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:management-personas'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM v_root_cause_quiet)"},{"type":"sql","name":"risk-clear","db":"AUDIT","sql":"DELETE FROM program_risk_now"},{"type":"sql","name":"risk-snapshot","db":"AUDIT","sql":"INSERT OR REPLACE INTO program_risk_now (program_code, manager_persona, verdict, risk, open_issues) SELECT program_code, manager_persona, verdict, risk, open_issues FROM v_program_risk"},{"type":"sql","name":"quality-snapshot","db":"AUDIT","sql":"INSERT OR REPLACE INTO quality_trend (tick, scope, measured, in_breach, reopens_7d, quality_index) SELECT strftime(''%Y-%m-%dT%H:00Z'', ''now''), ''fleet'', COUNT(*), SUM(CASE WHEN v.hit = 1 THEN 1 ELSE 0 END), (SELECT COALESCE(SUM(reopens_7d), 0) FROM issue_recurrence_now), ROUND(100.0 * SUM(CASE WHEN v.hit = 1 THEN 0 ELSE 1 END) / MAX(1, COUNT(*)), 1) FROM v_metric_trigger_state v WHERE v.val IS NOT NULL UNION ALL SELECT strftime(''%Y-%m-%dT%H:00Z'', ''now''), c.program_code, COUNT(v.id), SUM(CASE WHEN v.hit = 1 THEN 1 ELSE 0 END), (SELECT COALESCE(SUM(reopens_7d), 0) FROM issue_recurrence_now n WHERE n.program_code = c.program_code), CASE WHEN COUNT(v.id) = 0 THEN NULL ELSE ROUND(100.0 * SUM(CASE WHEN v.hit = 1 THEN 0 ELSE 1 END) / COUNT(v.id), 1) END FROM program_charters c LEFT JOIN service_program_map s ON s.program_code = c.program_code LEFT JOIN v_metric_trigger_state v ON v.owner = s.service AND v.val IS NOT NULL WHERE c.status = ''active'' GROUP BY c.program_code"},{"type":"sql","name":"metric-quality","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT quality_index FROM quality_trend WHERE scope = ''fleet'' AND tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''fleet_quality_index''"},{"type":"sql","name":"metric-reopens","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COALESCE(SUM(reopens_7d), 0) FROM issue_recurrence_now) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''issue_reopens_7d''"},{"type":"sql","name":"portfolio-allocate","db":"AUDIT","sql":"INSERT OR REPLACE INTO portfolio_allocations (tick, program_code, manager_persona, verdict, risk_score, risk_24h, open_issues, slots, decision, reason) SELECT strftime(''%Y-%m-%dT%H:00Z'', ''now''), program_code, manager_persona, verdict, risk, risk_24h, open_issues, slots, decision, reason FROM v_portfolio_allocation_plan"},{"type":"sql","name":"plan-clear","db":"AUDIT","sql":"DELETE FROM program_focus_plan_now"},{"type":"sql","name":"plan-snapshot","db":"AUDIT","sql":"INSERT OR REPLACE INTO program_focus_plan_now (program_code, issue_id, rank, tier, has_doer, reason) SELECT program_code, issue_id, rank, tier, has_doer, reason FROM v_program_focus_plan"},{"type":"sql","name":"focus-exit-log","db":"AUDIT","sql":"INSERT INTO program_focus_log (program_code, issue_id, action, reason) SELECT f.program_code, f.issue_id, CASE WHEN COALESCE((SELECT a.status FROM agent_issues a WHERE a.id = f.issue_id), ''missing'') <> ''open'' THEN ''closed'' ELSE ''exit'' END, CASE WHEN COALESCE((SELECT a.status FROM agent_issues a WHERE a.id = f.issue_id), ''missing'') <> ''open'' THEN ''issue '' || COALESCE((SELECT a.status FROM agent_issues a WHERE a.id = f.issue_id), ''missing'') ELSE ''outranked or outside the program slots'' END FROM program_focus f WHERE NOT EXISTS (SELECT 1 FROM program_focus_plan_now p WHERE p.program_code = f.program_code AND p.issue_id = f.issue_id)"},{"type":"sql","name":"focus-exit","db":"AUDIT","sql":"DELETE FROM program_focus WHERE NOT EXISTS (SELECT 1 FROM program_focus_plan_now p WHERE p.program_code = program_focus.program_code AND p.issue_id = program_focus.issue_id)"},{"type":"sql","name":"focus-enter-log","db":"AUDIT","sql":"INSERT INTO program_focus_log (program_code, issue_id, action, reason) SELECT p.program_code, p.issue_id, ''enter'', ''rank '' || p.rank || '': '' || p.reason FROM program_focus_plan_now p WHERE NOT EXISTS (SELECT 1 FROM program_focus f WHERE f.program_code = p.program_code AND f.issue_id = p.issue_id)"},{"type":"sql","name":"focus-enter","db":"AUDIT","sql":"INSERT OR IGNORE INTO program_focus (program_code, issue_id, rank, tier, reason, has_doer, last_tick) SELECT program_code, issue_id, rank, tier, reason, has_doer, strftime(''%Y-%m-%dT%H:00Z'', ''now'') FROM program_focus_plan_now"},{"type":"sql","name":"focus-refresh","db":"AUDIT","sql":"UPDATE program_focus SET rank = (SELECT p.rank FROM program_focus_plan_now p WHERE p.program_code = program_focus.program_code AND p.issue_id = program_focus.issue_id), tier = (SELECT p.tier FROM program_focus_plan_now p WHERE p.program_code = program_focus.program_code AND p.issue_id = program_focus.issue_id), reason = (SELECT p.reason FROM program_focus_plan_now p WHERE p.program_code = program_focus.program_code AND p.issue_id = program_focus.issue_id), has_doer = (SELECT p.has_doer FROM program_focus_plan_now p WHERE p.program_code = program_focus.program_code AND p.issue_id = program_focus.issue_id), last_tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')"},{"type":"sql","name":"scores-clear","db":"AUDIT","sql":"DELETE FROM issue_priority_scores WHERE scored_by LIKE ''program-manager:%'' AND NOT EXISTS (SELECT 1 FROM program_focus f WHERE f.issue_id = issue_priority_scores.issue_id AND issue_priority_scores.scored_by = ''program-manager:'' || f.program_code)"},{"type":"sql","name":"scores-set","db":"AUDIT","sql":"INSERT OR IGNORE INTO issue_priority_scores (issue_id, impact, probability, capability_gain, reach_gain, remediation_cost, scored_by, note) SELECT issue_id, 5, 5, 5, 5, 1, ''program-manager:'' || program_code, ''MANAGEMENT-PERSONAS-1 focus rank '' || rank || '' ('' || reason || '')'' FROM program_focus"},{"type":"sql","name":"promote-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || f.program_code, ''promote'', f.issue_id, a.priority, ''high'', ''in program focus at rank '' || f.rank || '' ('' || f.reason || '')'' FROM program_focus f JOIN agent_issues a ON a.id = f.issue_id WHERE a.status = ''open'' AND a.priority IN (''medium'', ''low'') AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off''"},{"type":"sql","name":"promote","db":"AUDIT","sql":"UPDATE agent_issues SET priority = ''high'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND priority IN (''medium'', ''low'') AND id IN (SELECT issue_id FROM program_focus) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off''"},{"type":"sql","name":"restore-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT p.persona_key, ''restore'', p.issue_id, ''high'', p.from_value, ''left program focus: priority restored to its value before promotion (action '' || p.id || '')'' FROM persona_actions p JOIN agent_issues a ON a.id = p.issue_id WHERE p.kind = ''promote'' AND p.reverted_at IS NULL AND a.status = ''open'' AND a.priority = ''high'' AND NOT EXISTS (SELECT 1 FROM program_focus f WHERE f.issue_id = p.issue_id)"},{"type":"sql","name":"restore","db":"AUDIT","sql":"UPDATE agent_issues SET priority = (SELECT p.from_value FROM persona_actions p WHERE p.kind = ''promote'' AND p.reverted_at IS NULL AND p.issue_id = agent_issues.id ORDER BY p.id DESC LIMIT 1), updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND priority = ''high'' AND id IN (SELECT p.issue_id FROM persona_actions p WHERE p.kind = ''promote'' AND p.reverted_at IS NULL) AND id NOT IN (SELECT issue_id FROM program_focus)"},{"type":"sql","name":"restore-mark","db":"AUDIT","sql":"UPDATE persona_actions SET reverted_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE kind = ''promote'' AND reverted_at IS NULL AND issue_id NOT IN (SELECT issue_id FROM program_focus)"},{"type":"sql","name":"recovered-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT issue_id, ''metric-recovered'', ''triaged'', ''management-personas'', datetime(''now''), evidence FROM v_persona_recovered_close WHERE 1 ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"recovered-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || COALESCE(program_code, ''QNFO.OPS''), ''close'', issue_id, ''open'', ''closed'', evidence FROM v_persona_recovered_close"},{"type":"sql","name":"recovered-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:management-personas'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM v_persona_recovered_close)"},{"type":"sql","name":"twin-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT issue_id, ''superseded-twin'', ''triaged'', ''management-personas'', datetime(''now''), evidence FROM v_persona_twin_supersede WHERE 1 ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"twin-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || COALESCE(program_code, ''QNFO.OPS''), ''supersede'', issue_id, ''open'', ''closed'', evidence FROM v_persona_twin_supersede"},{"type":"sql","name":"twin-contracts","db":"AUDIT","sql":"UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:twin-of-'' || (SELECT t.successor FROM v_persona_twin_supersede t WHERE t.issue_id = remediation_contracts.issue_id), last_attempt_at = datetime(''now'') WHERE issue_id IN (SELECT issue_id FROM v_persona_twin_supersede) AND status IN (''active'', ''holding'', ''needs-machine-probe'', ''probe-review-refused'')"},{"type":"sql","name":"twin-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:management-personas'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM v_persona_twin_supersede)"},{"type":"sql","name":"demote-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''portfolio-manager'', ''demote'', issue_id, ''critical'', ''high'', evidence FROM v_portfolio_critical_demote"},{"type":"sql","name":"demote","db":"AUDIT","sql":"UPDATE agent_issues SET priority = ''high'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM v_portfolio_critical_demote)"},{"type":"sql","name":"brief-programs","db":"AUDIT","sql":"INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT a.tick, a.manager_persona, ''program'', a.program_code, a.verdict, a.decision, a.program_code || '' is '' || a.verdict || '' at risk '' || a.risk_score || COALESCE('' (24h ago '' || a.risk_24h || '')'', '''') || ''. Aim: '' || COALESCE((SELECT c.objective FROM program_charters c WHERE c.program_code = a.program_code), ''no charter'') || '' Portfolio decision: '' || a.decision || '' with '' || a.slots || '' focus slot(s) ('' || a.reason || ''). Focus: '' || COALESCE((SELECT group_concat(x, ''; '') FROM (SELECT ''#'' || f.issue_id || '' '' || substr(i.title, 1, 90) || '' ['' || f.reason || CASE WHEN f.has_doer = 1 THEN '''' ELSE '', no doer yet'' END || '']'' AS x FROM program_focus f JOIN agent_issues i ON i.id = f.issue_id WHERE f.program_code = a.program_code ORDER BY f.rank)), ''none'') || ''. Top adopted goal: '' || COALESCE((SELECT g.goal_key || '': '' || substr(g.statement, 1, 120) FROM goals g WHERE g.program_code = a.program_code AND g.status = ''adopted'' AND g.goal_type <> ''objective-revision'' ORDER BY g.priority DESC, g.adopted_at LIMIT 1), ''none'') || ''.'' FROM portfolio_allocations a WHERE a.tick = (SELECT MAX(tick) FROM portfolio_allocations)"},{"type":"sql","name":"brief-portfolio","db":"AUDIT","sql":"INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT cur.tick, ''portfolio-manager'', ''portfolio'', ''QNFO'', CASE WHEN (SELECT COUNT(*) FROM portfolio_allocations WHERE tick = cur.tick AND verdict = ''RED'') > 0 THEN ''RED'' WHEN (SELECT COUNT(*) FROM portfolio_allocations WHERE tick = cur.tick AND verdict = ''AMBER'') > 0 THEN ''AMBER'' ELSE ''GREEN'' END, ''allocate'', ''Constraint: '' || COALESCE((SELECT program_code || '' (risk '' || risk_score || '')'' FROM portfolio_allocations WHERE tick = cur.tick AND decision = ''constrain'' LIMIT 1), ''none'') || '' of portfolio risk '' || (SELECT ROUND(SUM(risk_score), 1) FROM portfolio_allocations WHERE tick = cur.tick) || ''. Focus slots: '' || (SELECT group_concat(program_code || '' '' || slots || '' '' || decision, '', '') FROM (SELECT program_code, slots, decision FROM portfolio_allocations WHERE tick = cur.tick ORDER BY slots DESC, program_code)) || ''. RED programs: '' || (SELECT COUNT(*) FROM portfolio_allocations WHERE tick = cur.tick AND verdict = ''RED'') || '' of '' || (SELECT COUNT(*) FROM portfolio_allocations WHERE tick = cur.tick) || ''. Focus moves last hour: '' || (SELECT COUNT(*) FROM program_focus_log WHERE action = ''enter'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' in, '' || (SELECT COUNT(*) FROM program_focus_log WHERE action IN (''exit'', ''closed'') AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' out. Focus issues closed in 24h: '' || (SELECT COUNT(*) FROM program_focus_log WHERE action = ''closed'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) || ''; focus issues with no doer yet: '' || (SELECT COUNT(*) FROM program_focus WHERE has_doer = 0) || ''. Priority mix of '' || (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'') || '' open issues: '' || (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND priority = ''critical'') || '' critical, '' || (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND priority = ''high'') || '' high.'' FROM (SELECT MAX(tick) AS tick FROM portfolio_allocations) cur WHERE cur.tick IS NOT NULL"},{"type":"sql","name":"brief-actions","db":"AUDIT","sql":"UPDATE persona_briefs SET summary = summary || '' Own decisions in the last hour: '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''promote'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' promoted, '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''restore'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' restored, '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''close'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' closed on recovered metrics, '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''supersede'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' duplicates superseded, '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''demote'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' stale criticals demoted, '' || (SELECT COUNT(*) FROM persona_actions WHERE kind = ''root-cause'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) || '' root-cause issues filed.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations)"},{"type":"sql","name":"brief-quality","db":"AUDIT","sql":"UPDATE persona_briefs SET summary = summary || '' Quality: '' || COALESCE((SELECT quality_index FROM quality_trend WHERE scope = ''fleet'' AND tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')), ''?'') || '' of 100 metrics on target'' || COALESCE('' (24 h ago '' || (SELECT quality_index FROM quality_trend WHERE scope = ''fleet'' AND tick <= strftime(''%Y-%m-%dT%H:00Z'', ''now'', ''-24 hours'') ORDER BY tick DESC LIMIT 1) || '')'', '''') || ''; '' || (SELECT COALESCE(SUM(reopens_7d), 0) FROM issue_recurrence_now) || '' reopens in 7 days. Most recurring: '' || COALESCE((SELECT group_concat(family || '' '' || reopens_7d, '', '') FROM (SELECT family, reopens_7d FROM issue_recurrence_now ORDER BY reopens_7d DESC LIMIT 3)), ''none'') || ''; open root-cause issues '' || (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''ROOT-CAUSE-1:%'') || ''.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations)"},{"type":"sql","name":"brief-quality-programs","db":"AUDIT","sql":"UPDATE persona_briefs SET summary = summary || '' Quality '' || COALESCE((SELECT q.quality_index FROM quality_trend q WHERE q.scope = persona_briefs.scope AND q.tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')), ''?'') || '' of 100'' || COALESCE('' (24 h ago '' || (SELECT q.quality_index FROM quality_trend q WHERE q.scope = persona_briefs.scope AND q.tick <= strftime(''%Y-%m-%dT%H:00Z'', ''now'', ''-24 hours'') ORDER BY q.tick DESC LIMIT 1) || '')'', '''') || '', '' || COALESCE((SELECT q.reopens_7d FROM quality_trend q WHERE q.scope = persona_briefs.scope AND q.tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')), 0) || '' reopens in 7 days.'' WHERE level = ''program'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations)"},{"type":"sql","name":"brief-outputs","db":"AUDIT","sql":"UPDATE persona_briefs SET summary = summary || '' Outputs (readers, reviewers and probes, per surface): '' || COALESCE((SELECT verdict || '', '' || better || '' better, '' || worse || '' worse, '' || flat || '' flat'' || CASE WHEN COALESCE(gaps, '''') <> '''' THEN '', unmeasured: '' || gaps ELSE '''' END FROM v_output_quality_headline LIMIT 1), ''not measured'') || ''.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations)"},{"type":"sql","name":"decision-log","db":"AUDIT","sql":"INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, surfaces_tested) SELECT ''portfolio-manager (MANAGEMENT-PERSONAS-1)'', ''program risk = 3*high + 0.3*open + 15*guard breaches + 2*stalled projects (v_program_risk); half of the focus slots go evenly to programs with open work, half by risk share'', ''allocation changed: '' || (SELECT group_concat(program_code || '' '' || slots || '' '' || decision, '', '') FROM portfolio_allocations WHERE tick = cur.tick), ''v_program_risk and v_metric_trigger_state at '' || cur.tick, ''applied: program_focus resynced and issue_priority_scores set for '' || (SELECT COUNT(*) FROM program_focus) || '' focus issues'', ''qnfo-audit program_focus and issue_priority_scores rows scored_by program-manager:*, which reorder v_issue_queue_v2 (code loop intake) within each priority tier'', ''Rollback line of migrations/2026-10-26-management-personas.sql'', ''portfolio-allocation'', ''program_focus_closed_24h >= 1 within 24 h'', ''qnfo-audit v_program_health, v_metric_trigger_state, agent_issues, issue_project_map'' FROM (SELECT MAX(tick) AS tick FROM portfolio_allocations) cur WHERE cur.tick IS NOT NULL AND NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.actor = ''portfolio-manager (MANAGEMENT-PERSONAS-1)'' AND d.evidence = ''v_program_risk and v_metric_trigger_state at '' || cur.tick AND d.action = ''allocation changed: '' || (SELECT group_concat(program_code || '' '' || slots || '' '' || decision, '', '') FROM portfolio_allocations WHERE tick = cur.tick)) AND EXISTS (SELECT 1 FROM portfolio_allocations a WHERE a.tick = cur.tick AND NOT EXISTS (SELECT 1 FROM portfolio_allocations p WHERE p.program_code = a.program_code AND p.slots = a.slots AND p.decision = a.decision AND p.tick = (SELECT MAX(t2.tick) FROM portfolio_allocations t2 WHERE t2.tick < cur.tick)))"},{"type":"sql","name":"decision-log-actions","db":"AUDIT","sql":"INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, surfaces_tested) SELECT ''management-personas (MANAGEMENT-PERSONAS-2)'', ''reversible issue decisions belong to the managers (owner directive 2026-10-26: delegate all decisions to fleet agents); each is in persona_actions with its prior value'', ''last hour: '' || (SELECT group_concat(kind || '' '' || n, '', '') FROM (SELECT kind, COUNT(*) AS n FROM persona_actions WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'') GROUP BY kind)), ''persona_actions rows since '' || strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes''), ''applied'', ''qnfo-audit agent_issues priority and status of the rows in persona_actions'', ''persona_actions holds from_value per row; set ops_config persona_actions = off to stop; Rollback line of migrations/2026-10-26-management-personas-2.sql'', ''manager-decisions'', ''program_focus_closed_24h >= 1 within 24 h'', ''qnfo-audit v_metric_trigger_state, remediation_contracts, program_focus'' WHERE EXISTS (SELECT 1 FROM persona_actions WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) AND NOT EXISTS (SELECT 1 FROM decision_log WHERE actor = ''management-personas (MANAGEMENT-PERSONAS-2)'' AND ts >= strftime(''%Y-%m-%dT%H:00:00Z'', ''now''))"},{"type":"sql","name":"metric-focus-closed","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM program_focus_log WHERE action = ''closed'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''program_focus_closed_24h''"},{"type":"sql","name":"metric-focus-no-doer","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM program_focus WHERE has_doer = 0) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''program_focus_without_doer''"},{"type":"sql","name":"metric-actions","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM persona_actions WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''persona_actions_24h''"},{"type":"sql","name":"prune","db":"AUDIT","sql":"DELETE FROM persona_briefs WHERE tick < strftime(''%Y-%m-%dT%H:00Z'', ''now'', ''-30 days'')"},{"type":"sql","name":"ledger","db":"AUDIT","sql":"INSERT OR IGNORE INTO cloud_ops_events (id, ts, kind, text, meta, job, status) SELECT ''management-personas-'' || strftime(''%Y%m%d%H%M%S'', ''now''), datetime(''now''), ''management-personas'', ''MANAGEMENT-PERSONAS-3: quality '' || COALESCE((SELECT quality_index FROM quality_trend WHERE scope = ''fleet'' AND tick = strftime(''%Y-%m-%dT%H:00Z'', ''now'')), ''?'') || '' | '' || (SELECT group_concat(program_code || '' '' || verdict || '' '' || slots || '' '' || decision, '' | '') FROM portfolio_allocations WHERE tick = (SELECT MAX(tick) FROM portfolio_allocations)) || '' | focus '' || (SELECT COUNT(*) FROM program_focus) || '' (no doer '' || (SELECT COUNT(*) FROM program_focus WHERE has_doer = 0) || '')'', NULL, ''management-personas'', ''ok''"}]}', 120000, 1, 3, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));


-- First root cause fixed from the recurrence reading (FM portfolio-umbrella-flap): "PORTFOLIO-GAP no-mapped-work umbrella" (#2993) was
-- reopened 133 times in 7 days. Its contract closes it when no open no-mapped-work gap is left outside QNFO.INFRA.* (derived
-- infrastructure stubs are expected there), but portfolio-autopilot's file-no-mapped-work-umbrella step re-files it whenever any
-- no-mapped-work gap is open, the 45 QNFO.INFRA.* stubs included: closed at :10 by verified-remediation, re-filed at :20, every hour.
-- The filer now uses the closer's condition.
UPDATE fleet_tasks
SET definition = replace(definition, 'FROM portfolio_gaps WHERE status=''open'' AND kind=''no-mapped-work'' ORDER BY entity LIMIT 20)',
      'FROM portfolio_gaps WHERE status=''open'' AND kind=''no-mapped-work'' AND entity NOT LIKE ''QNFO.INFRA.%'' ORDER BY entity LIMIT 20)'),
    version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'portfolio-autopilot' AND instr(definition, 'kind=''no-mapped-work'' ORDER BY entity LIMIT 20)') > 0;

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('portfolio-umbrella-flap',
  'an issue closed by its contract is re-filed by its filer within the hour, every hour',
  'the filer (portfolio-autopilot file-no-mapped-work-umbrella) and the closing probe (issue-2993) tested different conditions: the probe excluded QNFO.INFRA.* stubs, the filer did not',
  'MANAGEMENT-PERSONAS-3: the filer uses the probe''s condition; the managers'' ROOT-CAUSE-1 loop surfaces any other family that flaps the same way',
  'fm-portfolio-umbrella-flap', 'fm-portfolio-umbrella-flap', '2026-10-26', 2993,
  'issue_lifecycle reopens of #2993 in 6 hours > 0', '133 reopens of #2993 in 7 days', 'issue_reopens_7d, issue throughput metrics, the owner''s view of open issues');

