   'falling; <= 100', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'MEASURED', NULL, NULL);

UPDATE management_personas
SET decision_authority = decision_authority || '; files one ROOT-CAUSE-1 issue per issue family that keeps reopening and closes it when the family stops recurring; measures the quality index of the fleet and of each program hourly (quality_trend) and escalates a program whose quality fell',
    updated_at = datetime('now')
WHERE (persona_key = 'portfolio:fleet' OR persona_key LIKE 'program:%') AND COALESCE(decision_authority, '') NOT LIKE '%ROOT-CAUSE-1%';

